```typescript
import { z } from 'zod';
import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { eventBus } from '../../orchestra/event-bus.js';
import { getCurrentSprintId } from '../../core/sprint-utils.js';

const WatchInput = z.object({
  sprintId: z.string().optional(),
  channels: z.array(z.enum(['PHASE', 'TASK_ASSIGN', 'HEARTBEAT', 'RESULT', 'ALERT', 'NOTIFY', 'METRIC'])).optional(),
  tail: z.number().min(0).max(100).default(20).optional(),
});

export function registerWatch(server: McpServer): void {
  server.registerTool('deckent_watch', {
    title: 'Subscribe to live sprint event stream via MCP notifications',
    description: 'Push-based subscription to sprint events via MCP notifications/message protocol. Auto-unsubscribes on client disconnect.',
    inputSchema: WatchInput.shape,
    annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  }, async (args) => {
    const sprintId = args.sprintId ?? getCurrentSprintId();
    const tailN = args.tail ?? 20;

    const recent = await eventBus.tail(sprintId, tailN);
    for (const event of recent) {
      if (args.channels && !args.channels.some(c => event.channel.includes(c))) continue;
      await server.server.sendLoggingMessage({
        level: event.channel.includes('ALERT') ? 'warning' : 'info',
        logger: `deckent.sprint.${sprintId}`,
        data: event,
      });
    }

    const unsubscribe = eventBus.subscribe(sprintId, args.channels as any, async (event) => {
      try {
        await server.server.sendLoggingMessage({
          level: event.channel.includes('ALERT') ? 'warning' : 'info',
          logger: `deckent.sprint.${sprintId}`,
          data: event,
        });
      } catch {
        unsubscribe();
      }
    });

    return {
      content: [{
        type: 'text',
        text: `Subscribed to sprint ${sprintId}. Backfilled ${recent.length} recent events. Channels: ${args.channels?.join(', ') ?? 'all'}.`,
      }],
    };
  });
}
```

